<div class="admin-panel admin-form-actions"><?php if($preview['rejected']===0):?><form method="post" action="/admin/products/import/confirm"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="token" value="<?= e($preview['token']) ?>"><label class="admin-check"><input type="checkbox" required><span>Confirmo el alta atómica de <?= e($preview['accepted']) ?> productos inactivos.</span></label><button class="admin-primary-button">Confirmar importación</button></form><?php endif?><a class="admin-secondary-button" href="/admin/products/import">Elegir otro archivo</a></div><?php endif?>
